/**
 * What happens to a tool's output when NO chat owns the call.
 *
 * Every agent tool request carries the DB thread id of the chat that issued it
 * (`AgentToolRequest.threadId`, resolved in the main process from the Codex
 * `_meta`). When the main process cannot tie a call to any chat, the id is
 * absent — and for a long time the renderer filled the gap with "the chat that
 * is open right now". That guess is the bug this module replaces: an image
 * generated by a caller nobody could name was drawn into, and permanently
 * anchored to, whichever conversation the user happened to be looking at
 * (2026-11: one user's log had 718 of 1,512 image calls without an owner).
 *
 * The rule now: an unowned call runs DETACHED.
 *   - the work is still done and still saved (history page, files on disk),
 *     so nothing that was paid for is lost and the calling agent still gets
 *     its file paths back;
 *   - nothing is shown in, or anchored to, any chat;
 *   - the user is told, globally, where the output went.
 */

import type { ArtifactSaveInfo, AttachmentRef } from '../../../../types/agent-timeline'
import { useAgentChatStore } from './store'

/**
 * Thread id handed to the attachments IPC for a detached call's files.
 *
 * Not a real thread: `AttachmentService.ingest` content-addresses the bytes on
 * disk first and only then records a metadata row, and when that row cannot be
 * written (no such thread) it still returns the on-disk path. So the file is
 * saved and the agent gets its path, while no chat's ATTACHMENTS panel lists
 * it. Same device as the main process's `'seedance'` pseudo thread.
 */
export const DETACHED_OUTPUT_THREAD_ID = 'detached'

const NOTICE_ID = 'tool-output-detached'

/**
 * A detached caller can produce hundreds of outputs in a row. Repeating the
 * notice for each would bury the chat; once per window is enough to say "this
 * is happening" without it re-appearing the instant it is dismissed.
 */
export const DETACHED_NOTICE_MIN_INTERVAL_MS = 10 * 60_000

let lastNoticeAt = Number.NEGATIVE_INFINITY

/** Tell the user — once per window, not once per output — that output went unshown. */
export function noteDetachedToolOutput(now: number = Date.now()): void {
  if (now - lastNoticeAt < DETACHED_NOTICE_MIN_INTERVAL_MS) return
  lastNoticeAt = now
  useAgentChatStore.getState().pushNotice({
    id: NOTICE_ID,
    kind: 'toolOutputDetached',
    level: 'info',
    message:
      '有一部分生成结果找不到所属的对话，所以没有显示在任何对话里；它们已保存，可以在历史记录 / 作品库里找到。',
  })
}

export function resetDetachedToolOutputForTest(): void {
  lastNoticeAt = Number.NEGATIVE_INFINITY
}

/**
 * The bubble a media tool reports into — or, for a detached call, nothing.
 *
 * One object instead of an `if (threadId)` around every store call: a media
 * tool updates its bubble from half a dozen places (begin, three failure
 * exits, resolve, save banner, artifact swap), and a single forgotten guard
 * would put that update back into the open chat.
 */
export interface GenerationBubble {
  /** Bubble item id; `undefined` when the call is detached (there is no bubble). */
  readonly itemId: string | undefined
  /** Live progress line while generating (video tasks). */
  progress(text: string): void
  resolve(artifacts: AttachmentRef[]): void
  fail(message: string): void
  annotate(save: ArtifactSaveInfo): void
  replaceArtifacts(artifacts: AttachmentRef[]): void
}

const DETACHED_BUBBLE: GenerationBubble = {
  itemId: undefined,
  progress: () => {},
  // The one moment worth telling the user about: output now exists where they
  // will not see it. A failure has nothing to show; it goes back to the agent.
  resolve: () => noteDetachedToolOutput(),
  fail: () => {},
  annotate: () => {},
  replaceArtifacts: () => {},
}

/**
 * Open the "generating" bubble in the chat that owns the call. With no owner
 * there is no bubble: the returned object swallows every update.
 */
export function openGenerationBubble(
  prompt: string,
  threadId: string | undefined,
  mediaKind?: 'video' | 'audio',
): GenerationBubble {
  if (!threadId) return DETACHED_BUBBLE
  const begin = useAgentChatStore.getState().beginImageGeneration
  const itemId = mediaKind ? begin(prompt, threadId, mediaKind) : begin(prompt, threadId)
  const store = () => useAgentChatStore.getState()
  return {
    itemId,
    progress: (text) => store().updateGenerationProgress(itemId, text, threadId),
    resolve: (artifacts) => store().resolveImageGeneration(itemId, artifacts, threadId),
    fail: (message) => store().failImageGeneration(itemId, message, threadId),
    annotate: (save) => store().annotateImageGeneration(itemId, save, threadId),
    replaceArtifacts: (artifacts) => store().replaceImageArtifacts(itemId, artifacts, threadId),
  }
}
